// Safety floor: the AI may raise urgency, never lower it below the phone's rule-based tier.
const body = $('Fall from phone').first().json.body;
const raw = String($input.first().json.output || '');
let ai = {};
try { ai = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) {}
const rank = { minor: 0, serious: 1, severe: 2 };
const sensorTier = body.sensor?.tier || 'serious';
const aiTier = rank[ai.tier] !== undefined ? ai.tier : sensorTier;
const tier = rank[aiTier] >= rank[sensorTier] ? aiTier : sensorTier;
const name = body.patient?.name || 'Your family member';
const map = body.location?.map || '';
const fallback = `${name} may have fallen (${tier}). ${body.spoken_reply ? 'They said: "' + body.spoken_reply + '".' : 'No reply.'} ${map}`;
return [{ json: {
  tier,
  ai_tier: ai.tier || null,
  reason: ai.reason || 'AI unavailable, using sensor result',
  caregiver_message: ai.caregiver_message || fallback,
  paramedic_handover: ai.paramedic_handover || fallback,
  spoken_reply: ai.spoken_reply || 'Help is being contacted. Stay still if you are hurt.',
  title: (body.kind === 'sos' ? 'SOS: ' : 'FALL ALERT: ') + name + ' - ' + tier.toUpperCase(),
  priority: tier === 'minor' ? 4 : 5,
  tags: tier === 'severe' ? 'rotating_light,ambulance' : 'warning',
  map,
  ntfy_topic: body.ntfy_topic || 'fallsense-demo',
  name
} }];
